<?php
/**
 * WPCom Tracking for WP Admin Page Views.
 *
 * @package automattic/jetpack-mu-wpcom
 */

namespace Automattic\Jetpack\Jetpack_Mu_Wpcom\Wpcom_Wpadmin_Page_View;

use WPCOMSH_Support_Session_Detect;

/**
 * Bump a Tracks stat for every wp-admin page view not generated by an Automattician.
 * This is possibly interesting on its own but will also be used as part of an
 * initiative to understand how much supply we're offering for live chat demand.
 * See https://nosaraproject.wordpress.com/2015/03/06/live-chat-stats/
 */
function wpcom_nosara_track_admin_page_views() {
	if ( do_not_track_a11ns() ) {
		return;
	}

	$is_simple_site = defined( 'IS_WPCOM' ) && IS_WPCOM;
	$is_atomic_site = ! $is_simple_site;

	global $current_user, $current_blog, $current_screen;

	if (
		! $current_user instanceof \WP_User ||
		! $current_screen instanceof \WP_Screen
	) {
		return;
	}

	$blog_id    = null;
	$user_types = array();

	if ( $is_simple_site ) {
		if ( ! $current_blog instanceof \WP_Site ) {
			return;
		}

		$blog_id    = $current_blog->blog_id;
		$user_types = \WPCOM_User::get_types();
	}

	if ( $is_atomic_site ) {
		$blog_id    = _wpcom_get_current_blog_id();
		$user_types = wpcom_atomic_get_user_types();
	}
	?>
	<script type="text/javascript">
		var _admin_pv_props = {
			from_page: '<?php echo esc_js( $current_screen->id ); ?>',
			is_block_editor: '<?php echo $current_screen->is_block_editor ? 'true' : 'false'; ?>',
			source: 'wp-admin',
			blog_id: '<?php echo esc_js( (string) $blog_id ); ?>',
			user_type: '<?php echo esc_js( implode( ',', $user_types ) ); ?>'
		};
		_tkq = window._tkq || [];
		_tkq.push( [ 'identifyUser', <?php echo (int) $current_user->ID; ?>, '<?php echo esc_js( $current_user->user_login ); ?>' ] );
		_tkq.push( [ 'recordEvent', 'wpcom_admin_page_view', _admin_pv_props ] );
	</script>
	<?php
}
add_action( 'admin_footer', __NAMESPACE__ . '\wpcom_nosara_track_admin_page_views' );

/**
 * Track non-calypso Customizer views if the user is linked from the frontend.
 */
function wpcom_maybe_track_customizer() {
	// not when the Customizer is loaded in Calypso
	if ( isset( $_GET['calypso'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		return;
	}

	// links from frontend
	if ( isset( $_GET['url'] ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		return wpcom_track_customizer_from_frontend();
	}

	// standard wp-admin
	wpcom_nosara_track_admin_page_views();
}

/**
 * Since links to the Customizer from the frontend aren't properly wp-admin (no wp-admin chrome,
 * you return to the frontend after closing), they shouldn't be counted as wp-admin views.
 */
function wpcom_track_customizer_from_frontend() {
	global $current_user;

	// Since we view so many screens to offer support and do feature dev, I think it's best not to count us.
	if ( do_not_track_a11ns() ) {
		return;
	}
	?>
	<script type="text/javascript">
		_tkq = window._tkq || [];
		_tkq.push( [ 'identifyUser', <?php echo (int) $current_user->ID; ?>, '<?php echo esc_js( $current_user->user_login ); ?>' ] );
		_tkq.push( [ 'recordEvent', 'wpcom_customize_loaded_from_frontend' ] );
	</script>
	<?php
}
add_action( 'customize_controls_print_footer_scripts', __NAMESPACE__ . '\wpcom_maybe_track_customizer' );

/**
 * Determine if the current user should not be tracked.
 *
 * @return bool
 */
function do_not_track_a11ns() {
	$is_simple_site = defined( 'IS_WPCOM' ) && IS_WPCOM;

	if ( $is_simple_site ) {
		return is_automattician() || is_network_admin();
	}

	return wpcom_atomic_maybe_is_a11n();
}

/**
 * Check if the user might be an a11n on Atomic sites.
 *
 * @return bool
 */
function wpcom_atomic_maybe_is_a11n() {
	$is_proxy_atomic    = defined( 'AT_PROXIED_REQUEST' ) && AT_PROXIED_REQUEST;
	$is_support_session = WPCOMSH_Support_Session_Detect::is_probably_support_session();

	return $is_proxy_atomic && ! $is_support_session;
}

/**
 * Retrieves the user types for Atomic sites.
 *
 * @return array An array of user types.
 */
function wpcom_atomic_get_user_types() {
	$user_types = array();

	if ( get_account_age_in_days() <= 14 ) {
		$user_types[] = 'New User';
	}

	$subscriptions = wpcomsh_get_wpcom_active_subscriptions();
	if ( count( $subscriptions ) > 0 ) {
		$user_types[] = 'Paid';
	}

	if ( wpcom_site_has_feature( \WPCOM_Features::PRIORITY_SUPPORT ) ) {
		$user_types[] = 'Business';
	}

	return $user_types;
}

/**
 * Calculate the number of days since the current user registered their account.
 *
 * @global WP_User $current_user The current user object.
 *
 * @return float The age of the account in days.
 */
function get_account_age_in_days() {
	global $current_user;

	return ( time() - strtotime( $current_user->user_registered ) ) / DAY_IN_SECONDS;
}

/**
 * Watch a request that resolved an admin screen, so it can be counted once the response settles.
 *
 * @param \WP_Screen $screen The screen WordPress resolved for this request.
 */
function wpcom_admin_screen_watch_request( $screen ) {
	if ( ! wpcom_admin_screen_is_countable( $screen ) ) {
		return;
	}

	// Deferred to shutdown because what the response turned out to be is only knowable once its
	// headers have settled, and admin_init has by then populated the user types below. Named
	// callback so a request that resolves its screen more than once still records one event.
	add_action( 'shutdown', __NAMESPACE__ . '\wpcom_admin_screen_record' );
}
add_action( 'current_screen', __NAMESPACE__ . '\wpcom_admin_screen_watch_request' );

/**
 * Whether wpcom_admin_page_view could also have reported this request. An exclusion on one side
 * but not the other makes the coverage percentage a measure of the disagreement between the two
 * events rather than of the tracking gap.
 *
 * @param \WP_Screen $screen The screen WordPress resolved for this request.
 * @return bool
 */
function wpcom_admin_screen_is_countable( $screen ) {
	// Atomic's only server-side delivery is a blocking 1s HTTP request per page view, which is
	// too expensive to run on every admin screen.
	if ( ! defined( 'IS_WPCOM' ) || ! IS_WPCOM ) {
		return false;
	}

	if ( ! $screen instanceof \WP_Screen ) {
		return false;
	}

	// Not is_admin(): it defers to the screen we were just handed, which reports itself as being
	// in the admin for every set_current_screen() caller, REST endpoints included.
	if ( ! defined( 'WP_ADMIN' ) || ! WP_ADMIN ) {
		return false;
	}

	// admin-ajax.php defines WP_ADMIN, and REST endpoints resolve a screen to simulate an admin
	// context. Neither renders a page.
	if ( wp_doing_ajax() || ( defined( 'REST_REQUEST' ) && REST_REQUEST ) ) {
		return false;
	}

	if ( ! is_user_logged_in() ) {
		return false;
	}

	// The Customizer runs no admin_footer, so its client-side counterpart comes from
	// wpcom_maybe_track_customizer(), which records nothing for a Calypso frame or a frontend link.
	if ( 'customize' === $screen->id && ( isset( $_GET['calypso'] ) || isset( $_GET['url'] ) ) ) { // phpcs:ignore WordPress.Security.NonceVerification.Recommended
		return false;
	}

	return ! do_not_track_a11ns();
}

/**
 * Whether the response the request produced was actually an admin screen.
 *
 * A redirect renders nothing and the screen it points at records itself, so counting both would
 * inflate the denominator on every admin POST. A download (export.php) or a bare fragment
 * (async-upload.php) resolves a screen and then exits without an admin footer, so the client
 * event never fires for it and counting it would depress the ratio the same way.
 *
 * @param string[] $headers Response headers, as returned by headers_list().
 * @return bool
 */
function wpcom_admin_screen_rendered( array $headers ) {
	$content_type = null;

	foreach ( $headers as $header ) {
		if ( 0 === stripos( $header, 'location:' ) ) {
			return false;
		}

		if ( 0 === stripos( $header, 'content-disposition:' ) && false !== stripos( $header, 'attachment' ) ) {
			return false;
		}

		if ( 0 === stripos( $header, 'content-type:' ) ) {
			$content_type = strtolower( ltrim( substr( $header, strlen( 'content-type:' ) ) ) );
		}
	}

	// A response that never got as far as a Content-Type is still countable: an early wp_die() or
	// a fatal is precisely the traffic this event exists to measure.
	if ( null === $content_type ) {
		return true;
	}

	return 0 === strpos( $content_type, 'text/html' ) || 0 === strpos( $content_type, 'application/xhtml+xml' );
}

/**
 * Record one Tracks event per rendered admin screen.
 *
 * @return void
 */
function wpcom_admin_screen_record() {
	if ( ! wpcom_admin_screen_rendered( headers_list() ) ) {
		return;
	}

	$screen = get_current_screen();
	if ( ! $screen instanceof \WP_Screen ) {
		return;
	}

	global $current_blog;
	if ( ! $current_blog instanceof \WP_Site ) {
		return;
	}

	// Called instead of wpcom_record_tracks_event() because that helper tests for
	// tracks_record_event() before require_lib() has had a chance to define it, and so drops
	// events whenever nothing else loaded the lib first.
	require_lib( 'tracks/client' );

	// Property names and value shapes are copied from wpcom_admin_page_view so that the two
	// events join per screen without a translation step in the query.
	tracks_record_event(
		wp_get_current_user(),
		'wpcom_admin_screen',
		array(
			'from_page'       => $screen->id,
			'is_block_editor' => $screen->is_block_editor ? 'true' : 'false',
			'source'          => 'wp-admin',
			'blog_id'         => (string) $current_blog->blog_id,
			'user_type'       => implode( ',', \WPCOM_User::get_types() ),
		)
	);
}
